{# TEMPLATE VAR SETTINGS #}
{%- set url_root = pathto('', 1) %}
{%- if url_root == '#' %}{% set url_root = '' %}{% endif %}
{%- if not embedded and docstitle %}
  {%- set titlesuffix = " &mdash; "|safe + docstitle|e %}
{%- else %}
  {%- set titlesuffix = "" %}
{%- endif %}
{%- set lang_attr = 'en' %}

<!DOCTYPE html>
<!--[if IE 8]><html class="no-js lt-ie9" lang="{{ lang_attr }}" > <![endif]-->
<!--[if gt IE 8]><!--> <html class="no-js" lang="{{ lang_attr }}" > <!--<![endif]-->
<head>
  <meta charset="utf-8">
  {{ metatags }}
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  {% block htmltitle %}
  <title>{{ title|striptags|e }}{{ titlesuffix }}</title>
  {% endblock %}
  <link rel="canonical" href="http://scikit-learn.org/stable/{{pagename}}.html" />

  {% if favicon_url %}
  <link rel="shortcut icon" href="{{ favicon_url|e }}"/>
  {% endif %}

  <link rel="stylesheet" href="{{ pathto('_static/css/vendor/bootstrap.min.css', 1) }}" type="text/css" />
  {%- for css in css_files %}
    {%- if css|attr("rel") %}
  <link rel="{{ css.rel }}" href="{{ pathto(css.filename, 1) }}" type="text/css"{% if css.title is not none %} title="{{ css.title }}"{% endif %} />
    {%- else %}
  <link rel="stylesheet" href="{{ pathto(css, 1) }}" type="text/css" />
    {%- endif %}
  {%- endfor %}
  <link rel="stylesheet" href="{{ pathto('_static/' + style, 1) }}" type="text/css" />
<script id="documentation_options" data-url_root="{{ pathto('', 1) }}" src="{{ pathto('_static/documentation_options.js', 1) }}"></script>
<script src="{{ pathto('_static/jquery.js', 1) }}"></script>
{%- block extrahead %} {% endblock %}
</head>
<body>
{% include "nav.html" %}
{%- block content %}
<div class="d-flex" id="sk-doc-wrapper">
    <input type="checkbox" name="sk-toggle-checkbox" id="sk-toggle-checkbox">
    <label id="sk-sidemenu-toggle" class="sk-btn-toggle-toc btn sk-btn-primary" for="sk-toggle-checkbox">Toggle Menu</label>
    <div id="sk-sidebar-wrapper" class="border-right">
      <div class="sk-sidebar-toc-wrapper">
        <div class="btn-group w-100 mb-2" role="group" aria-label="rellinks">
          {%- if prev %}
            <a href="{{ prev.link|e }}" role="button" class="btn sk-btn-rellink py-1" sk-rellink-tooltip="{{ prev.title|striptags }}">Prev</a>
          {%- else %}
            <a href="#" role="button" class="btn sk-btn-rellink py-1 disabled"">Prev</a>
          {%- endif %}
          {%- if parents -%}
            <a href="{{ parents[-1].link|e }}" role="button" class="btn sk-btn-rellink py-1" sk-rellink-tooltip="{{ parents[-1].title|striptags }}">Up</a>
          {%- else %}
            <a href="#" role="button" class="btn sk-btn-rellink disabled py-1">Up</a>
          {%- endif %}
          {%- if next %}
            <a href="{{ next.link|e }}" role="button" class="btn sk-btn-rellink py-1" sk-rellink-tooltip="{{ next.title|striptags }}">Next</a>
          {%- else %}
            <a href="#" role="button" class="btn sk-btn-rellink py-1 disabled"">Next</a>
          {%- endif %}
        </div>
        {%- if pagename != "install" %}
        <div class="alert alert-warning p-1 mb-2" role="alert">
          <p class="text-center mb-0">
          <strong>LangChain {{ release }}</strong><br/>
          </p>
        </div>
        {%- endif %}
            {%- if meta and meta['parenttoc']|tobool %}
            <div class="sk-sidebar-toc">
            {% set nav = get_nav_object(maxdepth=3, collapse=True, numbered=True) %}
              <ul>
              {% for main_nav_item in nav %}
              {% if main_nav_item.active %}
              <li>
                <a href="{{ main_nav_item.url }}" class="sk-toc-active">{{ main_nav_item.title }}</a>
              </li>
              <ul>
              {% for nav_item in main_nav_item.children %}
                <li>
                  <a href="{{ nav_item.url }}" class="{% if nav_item.active %}sk-toc-active{% endif %}">{{ nav_item.title }}</a>
                  {% if nav_item.children %}
                  <ul>
                    {% for inner_child in nav_item.children %}
                      <li class="sk-toctree-l3">
                        <a href="{{ inner_child.url }}">{{ inner_child.title }}</a>
                      </li>
                    {% endfor %}
                  </ul>
                  {% endif %}
                </li>
              {% endfor %}
              </ul>
              {% endif %}
              {% endfor %}
              </ul>
            </div>
            {%- elif meta and meta['globalsidebartoc']|tobool %}
            <div class="sk-sidebar-toc sk-sidebar-global-toc">
              {{ toctree(maxdepth=2, titles_only=True) }}
            </div>
            {%- else %}
            <div class="sk-sidebar-toc">
              {{ toc }}
            </div>
            {%- endif %}
      </div>
    </div>
    <div id="[REDACTED]">
      <div class="sk-page-content container-fluid body px-md-3" role="main">
        {% block body %}{% endblock %}
      </div>
    <div class="container">
      <footer class="sk-content-footer">
        {%- if pagename != 'index' %}
        {%- if show_copyright %}
          {%- if hasdoc('copyright') %}
            {% trans path=pathto('copyright'), copyright=copyright|e %}&copy; {{ copyright }}.{% endtrans %}
          {%- else %}
            {% trans copyright=copyright|e %}&copy; {{ copyright }}.{% endtrans %}
          {%- endif %}
        {%- endif %}
        {%- if last_updated %}
          {% trans last_updated=last_updated|e %}Last updated on {{ last_updated }}.{% endtrans %}
        {%- endif %}
        {%- if show_source and has_source and sourcename %}
          <a href="{{ pathto('_sources/' + sourcename, true)|e }}" rel="nofollow">{{ _('Show this page source') }}</a>
        {%- endif %}
        {%- endif %}
      </footer>
    </div>
  </div>
</div>
{%- endblock %}
<script src="{{ pathto('_static/js/vendor/bootstrap.min.js', 1) }}"></script>
{% include "javascript.html" %}
</body>
</html>

{%- extends "basic/search.html" %}
{% block extrahead %}
  <script type="text/javascript" src="{{ pathto('_static/underscore.js', 1) }}"></script>
  <script type="text/javascript" src="{{ pathto('searchindex.js', 1) }}" defer></script>
  <script type="text/javascript" src="{{ pathto('_static/doctools.js', 1) }}"></script>
  <script type="text/javascript" src="{{ pathto('_static/language_data.js', 1) }}"></script>
  <script type="text/javascript" src="{{ pathto('_static/searchtools.js', 1) }}"></script>
  <!-- <script type="text/javascript" src="{{ pathto('_static/sphinx_highlight.js', 1) }}"></script> -->
  <script type="text/javascript">
    $(document).ready(function() {
      if (!Search.out) {
        Search.init();
      }
    });
  </script>
{% endblock %}

{%- if pagename != 'index' and pagename != 'documentation' %}
  {%- set nav_bar_class = "sk-docs-navbar" %}
  {%- set top_container_cls = "sk-docs-container" %}
{%- else %}
  {%- set nav_bar_class = "sk-landing-navbar" %}
  {%- set top_container_cls = "sk-landing-container" %}
{%- endif %}

{% if theme_link_to_live_contributing_page|tobool %}
{# Link to development page for live builds #}
  {%- set development_link = "https://scikit-learn.org/dev/developers/index.html" %}
{# Open on a new development page in new window/tab for live builds #}
  {%- set development_attrs = 'target="_blank" rel="noopener noreferrer"' %}
{%- else %}
  {%- set development_link = pathto('developers/index') %}
  {%- set development_attrs = '' %}
{%- endif %}


<nav id="navbar" class="{{ nav_bar_class }} navbar navbar-expand-md navbar-light bg-light py-0">
  <div class="container-fluid {{ top_container_cls }} px-0">
    {%- if logo_url %}
      <a class="navbar-brand py-0" href="{{ pathto('index') }}">
        <img
          class="sk-brand-img"
          src="{{ logo_url|e }}"
          alt="logo"/>
      </a>
    {%- endif %}
    <button
      id="sk-navbar-toggler"
      class="navbar-toggler"
      type="button"
      data-toggle="collapse"
      data-target="#navbarSupportedContent"
      aria-controls="navbarSupportedContent"
      aria-expanded="false"
      aria-label="Toggle navigation"
    >
      <span class="navbar-toggler-icon"></span>
    </button>

    <div class="sk-navbar-collapse collapse navbar-collapse" id="navbarSupportedContent">
      <ul class="navbar-nav mr-auto">
        <li class="nav-item">
          <a class="sk-nav-link nav-link" href="{{ pathto('api_reference') }}">API</a>
        </li>
        <li class="nav-item">
          <a class="sk-nav-link nav-link" target="_blank" rel="noopener noreferrer" href="https://python.langchain.com/">Python Docs</a>
        </li>
        {%- for title, link, link_attrs in drop_down_navigation %}
        <li class="nav-item">
          <a class="sk-nav-link nav-link nav-more-item-mobile-items" href="{{ link }}" {{ link_attrs }}>{{ title }}</a>
        </li>
        {%- endfor %}
      </ul>
      {%- if pagename != "search"%}
      <div id="searchbox" role="search">
          <div class="searchformwrapper">
          <form class="search" action="{{ pathto('search') }}" method="get">
            <input class="sk-search-text-input" type="text" name="q" aria-labelledby="searchlabel" />
            <input class="sk-search-text-btn" type="submit" value="{{ _('Go') }}" />
          </form>
          </div>
      </div>
      {%- endif %}
    </div>
  </div>
</nav>

/* Elements */
a {
  color: #2878A2;
  word-wrap: break-word;
}

a:focus {
  outline: none;
}

/* Anchor links */

a.headerlink {
  color: #c60f0f;
  font-size: 0.8em;
  padding: 0 4px 0 4px;
  text-decoration: none;
  visibility: hidden;
}

a.headerlink:hover {
  background-color: #c60f0f;
  color: white;
}

p {
  word-break: break-word;
  hyphens: auto;
}

input:focus {
  outline: none;
}

code {
  color: #222;
  background-color: #ecf0f3;
  border-radius: 0.2rem;
  padding: 0.15rem;
  word-break: normal;
}

nav {
  z-index: 3;
}

h1 code, h2 code, h3 code, h4 code, h5 code, h6 code {
  background-color: transparent;
}

h4 .section-number, h5 .section-number, h6 .section-number {
  display: none;
}

h1:hover a.headerlink,
h2:hover a.headerlink,
h3:hover a.headerlink,
h4:hover a.headerlink,
h5:hover a.headerlink,
h6:hover a.headerlink,
dt:hover a.headerlink {
  visibility: visible;
}

strong {
  font-weight: bold;
}

a code {
  color: inherit;
}

a code {
  background-color: transparent;
  font-weight: bold;
  color: #2878A2;
  border-radius: 0;
  padding: 0;
  white-space: nowrap;
}

img {
   max-width: 100%;
}

span.highlighted {
    background-color: #fbe54e;
}

div.highlight {
  border: 1px solid #ddd;
  margin-bottom: 1rem;
}

div.highlight pre {
  padding: 0.2rem 0.5rem;
  margin-bottom: 0;
  line-height: 1.2rem;
}

div.highlight a {
  text-decoration: underline;
}

.versionmodified {
  font-style: italic;
}

a.sk-landing-btn {
  background-color: #ff9c34;
  color: black;
  cursor: pointer;
  font-size: 1.1rem;
  font-weight: 500;
}

a.sk-landing-btn:hover {
  background-color: #45bf7b;
}

.sk-donate-btn {
  cursor: pointer;
}

.sk-page-content div.logo {
  float: left;
  width: 200px;
}

@media screen and (min-width: 992px) {
  .sk-page-content {
    padding-left: 2rem!important;
    padding-right: 2rem!important;
  }
}

@media screen and (min-width: 1200px) {
  .sk-px-xl-4 {
    padding-left: 1.3rem!important;
    padding-right: 1.3rem!important;
  }
}

/* clearfix */

div.clearer {
  clear: both;
}

/* details / summary */

div.sk-page-content details {
    margin: 4ex 0pt;
}

div.sk-page-content summary.btn {
    display: list-item;
    padding: 6px 20px;
    border: 1pt solid #999;
}

div.sk-page-content details div.card {
    padding: 0pt .5ex;
    margin: 1ex 0pt;
    border: 1px solid #e9ecef;
    border-left-width: .25rem;
    border-radius: .25rem;
    background: rgb(250, 252, 253)
}

div.sk-page-content summary {
  position: relative; /* Needed for the tooltips */
}

div.sk-page-content summary .tooltiptext {
  visibility: hidden;
  width: 120px;
  background-color: black;
  color: #fff;
  text-align: center;
  border-radius: 6px;
  padding: 5px 0;
  position: absolute;
  z-index: 1;
  bottom: 150%;
  left: 50%;
  margin-left: -60px;
}

div.sk-page-content summary .tooltiptext::after {
  content: "";
  position: absolute;
  top: 100%;
  left: 50%;
  margin-left: -5px;
  border-width: 5px;
  border-style: solid;
  border-color: black transparent transparent transparent;
}

div.sk-page-content summary:hover .tooltiptext {
  visibility: visible;
}

/* Button */

.sk-btn-primary {
  background-color: #30799C;
  border-color: #30799C;
  color: white;
}

.sk-btn-primary:hover,
.sk-btn-primary:active {
  background-color: #3499cd;
  border-color: #3499cd;
}

/* Quote */

.quote {
  text-align: right;
  line-height: 1.5em;
  font-style: italic;
  margin: 2em 3em 1em 3em;
}

.line-block {
  display: block;
  margin-top: 1em;
  margin-bottom: 1em;
}

/* Search */

#search-results {
  margin-top: 1rem;
}

#searchbox {
  padding-top: 0.1rem;
}

.sk-search-text-input {
  width: 12rem;
}

.sk-search-text-btn {
  padding-left: 0.2rem;
  padding-right: 0.2rem;
}

ul.search li div.context {
  color: #888;
  margin: 0.1rem 0 0 0;
  text-align: left;
}

@media screen and (min-width: 768px) {
  ul.search li div.context {
    margin-left: 1rem;
  }

  .sk-search-text-input {
    width: 5rem;
  }
}

@media screen and (min-width: 806px) {
  .sk-search-text-input {
    width: 7rem;
  }
}

@media screen and (min-width: 820px) {
  .sk-search-text-input {
    width: 8rem;
  }
}

@media screen and (min-width: 886px) {
  .sk-search-text-input {
    width: 12rem;
  }
}

ul.search li a {
  font-weight: bold;
}
/* navbar */

img.sk-brand-img {
  height: 48px;
}

.navbar-light .navbar-nav a.nav-link, a.sk-dropdown-item  {
  color: rgba(77, 77, 77, 1);
  font-weight: 500;
}

.navbar-light .navbar-nav a.nav-link:hover, a.sk-dropdown-item:hover {
  color: rgba(246, 126, 0, 1);
}

a.sk-nav-dropdown-item:active {
  color: white;
  background-color: rgba(246, 126, 0, 1);
}

.nav-more-item-mobile-items {
  display: inherit;
}

.nav-more-item-dropdown {
  display: none;
}

@media screen and (min-width: 768px) {
  .nav-more-item-dropdown {
    display: inherit;
  }

  .nav-more-item-mobile-items {
    display: none;
  }
}
/* LANDING PAGE STYLE */

div.sk-landing-container {
  max-width: 1400px;
}

div.sk-landing-container .text-white {
    text-shadow: 0px 0px 8px rgb(42, 98, 128);
}

ul.sk-landing-header-body {
  margin-top: auto;
  margin-bottom: auto;
  font-size: 1.2rem;
  font-weight: 500;
}

div.[REDACTED] dd {
  padding-left: 0;
}

div.sk-landing-bg {
  background-image: linear-gradient(160deg, rgba(42,98,128,1) 0%, rgba(52,153,205,1) 17%, rgba(255,243,211,1) 59%, rgba(255,178,96,1) 100%);
}

div.[REDACTED] {
  background-color: #f8f8f8;
  font-size: 0.96rem;
}

.sk-card-title {
  font-weight: 700;
}

.sk-landing-header {
  font-size: 3.2rem;
}

.sk-landing-subheader {
  letter-spacing: 0.17rem;
}

.sk-landing-call-header {
  color: #E07200;
  font-weight: 700;
}

img.sk-index-img {
  max-height: 240px;
  margin: auto;
  margin-bottom: 1em;
  width: auto;
}

@media screen and (min-width: 768px) {
  img.sk-index-img {
    width: 100%
  }
}

img.[REDACTED] {
  max-height: 100px;
  max-width: 50%;
}

div#carouselExampleSlidesOnly {
  min-height: 200px;
}

ul.sk-landing-call-list li {
  margin-bottom: 0.25rem;
}

img.sk-footer-funding-logo {
  max-height: 36px;
  max-width: 80px;
  margin: 0 8px;
  margin-bottom: 8px;
}

a.sk-footer-funding-link:hover {
  text-decoration: none;
}
/* DOCS STYLE */

.navbar > .sk-docs-container {
  max-width: 1400px;
  margin: 0 auto;
}

#sk-sidebar-wrapper {
  height: 100%;
  overflow-y: hidden;
  overflow-x: hidden;
  position: fixed;
  margin-left: -240px;
  width: 240px;
  -webkit-transition: margin 0.25s ease-out, opacity 0.25s ease-out;
  -moz-transition: margin 0.25s ease-out, opacity 0.25s ease-out;
  -o-transition: margin 0.25s ease-out, opacity 0.25s ease-out;
  transition: margin 0.25s ease-out, opacity 0.25s ease-out;
  background-color: white;
  opacity: 0;
  top: 0;
  padding: 0 0.5rem 0.5rem 0.5rem;
  z-index: 2;
}

#sk-toggle-checkbox {
  display: none;
}

#sk-toggle-checkbox:checked ~ #sk-sidebar-wrapper {
  margin-left: 0;
  opacity: 1;
}

#sk-doc-wrapper {
  max-width: 1400px;
  margin: 0 auto;
}

#[REDACTED] {
  width: 100%;
}

/* Enables section links to be visible when anchor-linked */
section[id]::before {
  display: block;
  height: 52px;
  margin-top: -52px;
  visibility: hidden;
  content: "";
}

div.sk-page-content {
  background-color: white;
  position: relative;
  margin-top: 0.5rem;
}

div.sk-page-content {
  table-layout: fixed;
  max-width: 100%;
}

div.section h2,
div.section h3,
div.section h4,
div.section h5,
div.section h6 {
  margin-top: 1rem;
}

.sk-btn-toggle-toc {
  position: fixed;
  bottom: 0;
  margin: 0;
  border-radius: 0;
  border-top-right-radius: 0.5rem;
  z-index: 3;
  cursor: pointer;
}

div.sk-page-content {
  margin-top: 52px;
}

@media screen and (min-width: 1400px) {
  .sk-btn-toggle-toc {
    border-top-left-radius: 0.5rem;
  }
}

.sk-btn-toggle-toc:hover {
  color: white;
  background-color: #297ca7;
}

footer.sk-content-footer {
  padding: 1rem 0;
  color: #999;
  text-align: right;
}

nav.sk-docs-navbar {
  width: 100%;
  z-index: 3;
  -webkit-transition: top .2s ease-in-out;
  -moz-transition: top .2s ease-in-out .05s;
  -o-transition: top .2s ease-in-out .05s;
  transition: top .2s ease-in-out .05s;
  position: fixed;
  max-height: 100vh;
  overflow-y: auto;
  align-items: initial;
}

div.sk-navbar-collapse {
  padding-bottom: 4rem;
}

@media screen and (min-width: 768px) {

  nav.sk-docs-navbar {
    overflow-y: visible;
    max-height: none;
  }

  div.sk-navbar-collapse {
    padding-bottom: 0;
  }

  #[REDACTED] {
    padding-left: 240px;
    max-width: 1240px;
    margin-left: auto;
    margin-right: auto;
  }

  #sk-sidebar-wrapper {
    margin-left: 0;
    opacity: 1;
  }

  #sk-toggle-checkbox:checked ~ #sk-sidebar-wrapper {
    margin-left: -240px;
    opacity: 0;
  }

  #sk-toggle-checkbox:checked ~ #[REDACTED] {
    padding-left: 0;
    margin-left: auto;
    margin-right: auto;
  }
}

.centered {
  text-align: center;
}

dl.citation > dd > ol > li {
  display: inline;
}

dl.citation > dd > ol {
  margin-bottom: 0;
}

/* docs index */

div.[REDACTED] {
  border-left: 0.15rem solid #ff9c34;
}
div.[REDACTED]:hover {
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

a.[REDACTED]:hover {
  text-decoration: none;
  color: #2878A2;
}

.[REDACTED] {
  background-color: #cde8ef;
  padding: 0.5rem;
  border-radius: 0 1rem;
  text-align: center;
  font-size: 2rem;
  font-weight: 500;
}

/* toc  */

.sk-toc-active {
  font-weight: bold;
}

div.sk-sidebar-toc-wrapper {
  font-size: 0.9rem;
  width: 252px;
  overflow-x: hidden;
  overflow-y: scroll;
  height: 100vh;
  padding-right: 1.75rem;
  padding-top: 52px;

  /* Hide scrollbar for IE and Edge */
  -ms-overflow-style: none;

  /* Hide scrollbar for Firefox */
  scrollbar-width: none;
}

div.sk-sidebar-toc-wrapper::-webkit-scrollbar {
  display: none;
}

div.sk-sidebar-toc-wrapper::after {
  display: block;
  content: "";
  height: 3rem;
  visibility: hidden;
}

div.sk-sidebar-toc > ul > li > a{
  font-weight: bold;
}

div.sk-sidebar-toc > ul,
div.sk-sidebar-toc ul ul {
  list-style: none;
  margin-left: 0;
  padding-left: 0;
}

div.sk-sidebar-toc ul ul ul {
  margin-left: 1rem;
}


div.sk-sidebar-toc ul li ul li ul{
  display: none;
}

div.sk-sidebar-toc span {
  white-space: pre;
}

div.sk-sidebar-global-toc ul ul {
  padding-left: 0.75rem;
}
/* content styling element style */

div.sk-page-content h1 {
  background-color: #cde8ef;
  padding: 0.5rem;
  margin-top: calc(max(2.5rem, 1vh));
  border-radius: 0 1rem;
  text-align: center;
  font-size: 2rem;
  word-wrap: break-word;
}

div.sk-page-content h2 {
  padding: 0.5rem;
  background-color: #BED4EB;
  border-radius: 0.3rem;
  font-size: 1.5rem;
  margin-top: calc(max(2rem, .7vh));
  margin-bottom: 1rem;
  word-wrap: break-word;
}

